import Foundation

/// Offline, source-preserving review. Base report and evidence revision bytes
/// are hashed independently; new reviews bind the revision, never the old report.
public enum VivoGenomicEvidenceHTML {
    public static func render(_ revision: VivoGenomicEvidenceRevision, parentData: Data) throws -> Data {
        try VivoAtlasEvidence.require(parentData.count <= 32 * 1024 * 1024 && (try VivoAtlasEvidence.digest(parentData)) == revision.binding.parentReportSHA256, "Display parent does not match the evidence revision.")
        let bytes = try VivoCanonicalJSON.encode(revision)
        let fingerprint = try VivoAtlasEvidence.digest(bytes)
        let html = #"""
        <!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
        <meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'">
        <title>NumiVivo · Genomic evidence review</title>
        <style>
        :root{color-scheme:light;--ink:#172b3c;--muted:#506576;--line:#d6e0e5;--bg:#f4f7f9;--blue:#174d6a;--violet:#655083}*{box-sizing:border-box}body{margin:0;font:15px/1.55 system-ui,-apple-system,sans-serif;color:var(--ink);background:var(--bg)}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}a{color:var(--blue)}.topbar{background:#112e41;color:white;padding:18px max(24px,calc((100vw - 1240px)/2));display:flex;justify-content:space-between;gap:16px}.brand{font-weight:750;letter-spacing:.03em}.tagline{font-size:12px;opacity:.85}main{max-width:1288px;margin:auto;padding:32px 24px 60px}h1{font-size:clamp(28px,4vw,43px);line-height:1.12;letter-spacing:-.03em;margin:12px 0}h2{font-size:20px;margin:0 0 12px}h3{font-size:19px;margin:0}p{margin:8px 0}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.13em;font-weight:700;color:var(--blue)}.muted{color:var(--muted)}.notice{background:#fff5dd;border:1px solid #dec995;padding:15px 18px;border-radius:10px;margin:24px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.metric,.panel,.candidate{background:white;border:1px solid var(--line);border-radius:11px;padding:20px}.metric strong{display:block;font-size:29px;line-height:1.2}.metric span{font-size:12px;color:var(--muted)}.panel{margin-top:22px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:16px 0}.toolbar label{flex:1;min-width:175px}label{display:block;font-size:13px;font-weight:650}input,select,textarea{width:100%;border:1px solid #9fadb8;border-radius:6px;padding:9px 11px;background:white;color:var(--ink)}textarea{resize:vertical;min-height:70px}button{border:0;border-radius:7px;background:var(--blue);color:white;padding:10px 15px;font-weight:650}.secondary{background:#e5edf1;color:var(--ink)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #8caec5;outline-offset:2px}.candidate{margin:14px 0}.head{display:flex;justify-content:space-between;align-items:start;gap:10px;flex-wrap:wrap}.badge{font-size:11px;font-weight:700;background:#eaf0f4;border-radius:5px;padding:4px 8px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.evidence{padding:16px;background:#f4f8fa;border-left:3px solid #6594a8;border-radius:6px}.prediction{background:#f6f3fa;border-left-color:#8c76a4}.section-label{font-size:11px;font-weight:750;letter-spacing:.06em;text-transform:uppercase;margin-bottom:9px}.fact{display:flex;justify-content:space-between;gap:12px;margin:5px 0;font-size:13px}.fact span:first-child{color:var(--muted)}.fact span:last-child{text-align:right;font-weight:600;overflow-wrap:anywhere}.peptide{font:600 17px ui-monospace,SFMono-Regular,monospace;letter-spacing:.05em;overflow-wrap:anywhere;margin:8px 0}.gap{font-size:13px;border-left:2px solid #ccb98f;margin:7px 0;padding-left:10px}.review{display:grid;grid-template-columns:230px 1fr;gap:12px;margin-top:16px}details{margin-top:12px}summary{font-weight:650;cursor:pointer}.table-scroll{overflow:auto;max-height:340px}table{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}th,td{padding:8px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left;overflow-wrap:anywhere}th{background:#f2f5f7}code{font-size:11px;overflow-wrap:anywhere}.pager{display:flex;justify-content:space-between;align-items:center;gap:12px}.footer{font-size:12px;color:var(--muted);margin-top:25px}#status{min-height:24px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:700px){main{padding:24px 14px}.topbar{padding:15px}.tagline{display:none}.metrics{grid-template-columns:1fr 1fr;gap:8px}.metric{padding:14px}.columns,.review{grid-template-columns:1fr}.panel,.candidate{padding:15px}.toolbar label{min-width:145px}.fact{flex-wrap:wrap}.fact span:last-child{text-align:left}}
        </style></head><body>
        <div class="topbar"><div class="brand">NumiVivo <span style="font-weight:400;opacity:.65">/ Research</span></div><div class="tagline">Local evidence review · no network requests</div></div>
        <main><header><div class="eyebrow">Genomic evidence workbench</div><h1>Measured evidence.<br>Predicted effects.<br>Separate conclusions.</h1><p class="muted">Review tumor observations, Atlas annotations and splice-derived candidates without collapsing them into a treatment score.</p></header>
        <div class="notice"><strong id="classification"></strong><p>Research review only. No treatment selection, manufacturing approval or demonstrated immune response is implied.</p></div>
        <div class="metrics"><div class="metric"><strong id="parentCount"></strong><span>Original candidate rows</span></div><div class="metric"><strong id="spliceCount"></strong><span>Splice candidate rows</span></div><div class="metric"><strong id="atlasCount"></strong><span>Atlas variants with data</span></div><div class="metric"><strong id="draftCount">0</strong><span>Research decisions drafted</span></div></div>
        <section class="panel"><h2>Case and evidence status</h2><p id="case"></p><p id="atlasSummary" class="muted"></p><p id="integrity" role="status">Checking local report integrity…</p><details><summary>Inspect provenance and limitations</summary><div id="provenance"></div><div id="limitations"></div></details></section>
        <section class="panel"><h2>Candidate review</h2><p class="muted">Original source order is retained. Predictions never remove evidence gaps. Only 25 candidate rows are rendered at a time.</p><div class="toolbar"><label>Search gene, transcript, HLA or peptide<input id="search" type="search" placeholder="Search candidates" autocomplete="off"></label><label>Evidence source<select id="sourceFilter"><option value="all">All candidates</option><option value="parent">Original pVACseq</option><option value="splice">Splice-derived candidates</option><option value="drafted">Drafted decisions</option></select></label></div><p id="empty" class="muted"></p><div id="candidates"></div><div class="pager"><button class="secondary" id="previous">Previous</button><span id="page" aria-live="polite"></span><button class="secondary" id="next">Next</button></div></section>
        <section class="panel"><h2>Save an evidence-bound research review</h2><p class="muted">This review references the new evidence revision. Previous report reviews do not authorize changed evidence. Reviewer identifiers are self-declared, not authenticated signatures.</p><div class="toolbar"><label>Reviewer identifier<input id="reviewer" maxlength="128" placeholder="researcher-01" autocomplete="off"></label><button id="export" disabled>Export review JSON</button></div><p id="status" role="status" aria-live="polite"></p><p class="muted">Drafts are held in page memory. Export before reloading or closing this page.</p></section>
        <div class="footer"><p>Revision SHA-256: <code id="digest"></code></p><p>Local browser checks verify bytes, not authorship or scientific truth. Native archive reconstruction remains a separate check.</p></div>
        </main><script>
        'use strict';
        const revisionEncoded='\#(bytes.base64EncodedString())',parentEncoded='\#(parentData.base64EncodedString())',expectedRevision='\#(fingerprint)';
        const unpack=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
        const revisionBytes=unpack(revisionEncoded),parentBytes=unpack(parentEncoded);
        const revision=JSON.parse(new TextDecoder().decode(revisionBytes)),parent=JSON.parse(new TextDecoder().decode(parentBytes));
        const $=id=>document.getElementById(id),text=(tag,value,cls)=>{const e=document.createElement(tag);e.textContent=String(value);if(cls)e.className=cls;return e},show=x=>x===null||x===undefined?'Not supplied':String(x);
        const drafts=new Map(),request=revision.atlasRequest,capture=revision.atlasCapture;let verified=false,page=0;
        const candidateVariants=new Map();for(const q of request?.variants||[])for(const id of q.candidateIDs)candidateVariants.set(id,q.key);
        const outcomes=new Map((capture?.outcomes||[]).map(o=>[o.variantKey,o]));
        const scorerRows=new Map();for(const t of capture?.tables||[])for(let i=0;i<t.observations.length;i++){const key=t.observations[i].variantKey;if(!scorerRows.has(key))scorerRows.set(key,[]);scorerRows.get(key).push({table:t,row:i})}
        const candidates=[...(parent.candidates||[]).map(c=>({...c,source:'parent',peptide:c.mutantPeptide})),...(revision.spliceReport?.candidates||[]).map(c=>({...c,source:'splice'}))];
        $('classification').textContent=revision.binding.dataClass==='synthetic'?'SYNTHETIC SOFTWARE DEMONSTRATION — not biological results':'PUBLIC REFERENCE DATA — research only';
        $('case').textContent=(parent.manifest?.caseID||'Reference case')+' · '+revision.binding.assembly+' · RNA sample '+revision.binding.tumorRNASampleID;
        $('parentCount').textContent=revision.parentCandidateIDs.length;$('spliceCount').textContent=revision.spliceReport?.candidates.length||0;
        $('atlasCount').textContent=(capture?.outcomes||[]).filter(o=>o.status==='available').length;$('digest').textContent=expectedRevision;
        $('atlasSummary').textContent=!request?'Atlas has not been requested for this revision.':!capture?'Atlas requests are prepared but have not been queried.':capture.mode==='fixture'?'Atlas values are invented software fixtures; no live service call occurred.':'Atlas capture: '+capture.retrievedAt+'. Failed and empty results remain distinct. Remote model version is not exposed by the pinned API.';
        function table(rows,headers){const wrap=text('div','','table-scroll'),t=document.createElement('table');if(headers){const tr=document.createElement('tr');for(const h of headers)tr.append(text('th',h));t.append(tr)}for(const values of rows){const tr=document.createElement('tr');for(const v of values)tr.append(text('td',v));t.append(tr)}wrap.append(t);return wrap}
        $('provenance').append(table([['Parent report',revision.binding.parentReportSHA256],['Case fingerprint',revision.binding.caseFingerprint],['Implementation',revision.implementationSHA256],['Source hashes',JSON.stringify(revision.sourceSHA256)],['Client commit',capture?.clientCommit||'Not supplied'],['Remote service version',capture?.serviceVersion||'Not exposed / not queried'],['Usage',capture?.permittedUse||'No Atlas capture'],['Training permission',capture?String(capture.trainingPermitted):'No Atlas capture']],['Record','Value']));
        for(const l of revision.limitations)$('limitations').append(text('p',l,'gap'));
        function fact(parent,label,value){const row=text('div','','fact');row.append(text('span',label),text('span',show(value)));parent.append(row)}
        function atlasView(c){const box=text('div','','evidence prediction');box.append(text('div','Atlas · predictive annotation','section-label'));const key=candidateVariants.get(c.id),excluded=request?.excludedCandidates?.[c.id];if(excluded){box.append(text('p',excluded));return box}if(!key||!capture){box.append(text('p',key?'Not queried. No score has been substituted.':'Not requested. No score has been substituted.'));return box}const o=outcomes.get(key);if(!o||o.status!=='available'){box.append(text('p',o?.status==='failed'?'Query failed: '+show(o.diagnostic):'No returned data for this query. This is not a low-impact result.'));return box}
          const groups=scorerRows.get(key)||[],total=groups.reduce((n,g)=>n+g.table.tracks.length,0),returned=new Set(groups.map(g=>g.table.scorer));
          box.append(text('p',capture.mode==='fixture'?'Invented prediction values — UI test only.':'Predicted molecular effects, not immune recognition.'));
          const missing=request.requestedScorers.filter(s=>!returned.has(s));if(missing.length)box.append(text('p','No returned rows for requested scorers: '+missing.join(', '),'gap'));
          const details=document.createElement('details');details.append(text('summary','Inspect '+total+' scorer / observation / track cells'));let shown=0,group=0,column=0;const holder=document.createElement('div'),more=text('button','Show more cells','secondary');more.type='button';
          function load(){const part=[];while(part.length<25&&group<groups.length){const g=groups[group],t=g.table,i=g.row,j=column;part.push([t.scorer+(t.isSigned?' · signed':' · unsigned'),JSON.stringify(t.observations[i].metadata),JSON.stringify(t.tracks[j]),show(t.rawScores[i][j]),show(t.quantiles?.[i]?.[j])]);column++;if(column>=t.tracks.length){group++;column=0}}shown+=part.length;holder.append(table(part,['Scorer','Gene / junction context','Tissue / track context','Raw score','Quantile']));more.hidden=shown>=total}
          details.addEventListener('toggle',()=>{if(details.open&&!shown)load()});more.addEventListener('click',load);details.append(holder,more);box.append(details);return box}
        function draw(){const query=$('search').value.trim().toLowerCase(),filter=$('sourceFilter').value;const matches=candidates.filter(c=>[c.gene,c.transcript,c.hlaAllele,c.peptide].join(' ').toLowerCase().includes(query)&&(filter==='all'||filter===c.source||(filter==='drafted'&&drafts.has(c.id))));page=Math.min(page,Math.max(0,Math.ceil(matches.length/25)-1));$('candidates').replaceChildren();
          for(const c of matches.slice(page*25,page*25+25)){const card=text('article','','candidate'),head=text('div','','head');head.append(text('h3',c.gene),text('span',c.source==='splice'?'Splice-derived · research':'Original pVACseq · research','badge'));card.append(head,text('div',c.peptide,'peptide'),text('p',c.hlaAllele+' · '+c.transcript,'muted'));
            const columns=text('div','','columns'),measured=text('div','','evidence');measured.append(text('div','Imported observations and checks','section-label'));for(const k of ['Tumor DNA Depth','Tumor DNA VAF','Tumor RNA Depth','Tumor RNA VAF','Normal Depth','Normal VAF','Gene Expression'])fact(measured,k,c.sourceFields[k]);if(c.source==='splice'){fact(measured,'RNA junction reads',c.junctionReadCount);fact(measured,'Junction',c.junctionID+' · '+c.strand);fact(measured,'ALT protein match','Position '+c.peptidePosition1);fact(measured,'Present in supplied WT',c.suppliedWildtypeContainsPeptide);fact(measured,'Consistency state',c.evidenceState)}card.append(text('p','Imported binding prediction: '+show(c.source==='splice'?c.medianBindingNM:c.predictedMedianBindingNM)+' nM · not an immune-recognition measurement.','muted'));columns.append(measured,atlasView(c));card.append(columns);
            const gaps=document.createElement('details');gaps.open=true;gaps.append(text('summary','Unresolved evidence'));for(const gap of c.evidenceGaps)gaps.append(text('p',gap,'gap'));card.append(gaps);
            const raw=document.createElement('details');raw.append(text('summary','Original source fields'));raw.addEventListener('toggle',()=>{if(raw.open&&!raw.dataset.loaded){raw.dataset.loaded='1';raw.append(table(Object.entries(c.sourceFields),['Field','Original value']));if(c.regtoolsFields)raw.append(table(Object.entries(c.regtoolsFields),['RegTools field','Original value']))}});card.append(raw);
            const controls=text('div','','review'),decisionLabel=text('label','Research disposition'),select=document.createElement('select');select.setAttribute('aria-label','Disposition for '+c.gene+' line '+c.sourceLine);for(const [v,l] of [['','Not reviewed'],['retainForResearch','Retain for research'],['exclude','Exclude'],['deferReview','Defer pending evidence']]){const option=text('option',l);option.value=v;select.append(option)}select.value=drafts.get(c.id)?.disposition||'';decisionLabel.append(select);const rationaleLabel=text('label','Rationale'),reason=document.createElement('textarea');reason.maxLength=4096;reason.setAttribute('aria-label','Rationale for '+c.gene+' line '+c.sourceLine);reason.value=drafts.get(c.id)?.rationale||'';rationaleLabel.append(reason);controls.append(decisionLabel,rationaleLabel);card.append(controls);
            const change=()=>{if(select.value)drafts.set(c.id,{candidateID:c.id,disposition:select.value,rationale:reason.value});else drafts.delete(c.id);$('draftCount').textContent=drafts.size};select.addEventListener('change',change);reason.addEventListener('input',change);$('candidates').append(card)
          }$('empty').textContent=matches.length?'Showing '+Math.min(matches.length,page*25+1)+'–'+Math.min(matches.length,(page+1)*25)+' of '+matches.length+' rows.':'No matching candidates. Empty output does not establish absence of neoantigens.';$('page').textContent='Page '+(page+1)+' of '+Math.max(1,Math.ceil(matches.length/25));$('previous').disabled=page===0;$('next').disabled=(page+1)*25>=matches.length
        }
        $('search').addEventListener('input',()=>{page=0;draw()});$('sourceFilter').addEventListener('change',()=>{page=0;draw()});$('previous').addEventListener('click',()=>{page--;draw()});$('next').addEventListener('click',()=>{page++;draw()});draw();
        const digest=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');
        (async()=>{try{if(!globalThis.crypto?.subtle)throw Error('unavailable');if(await digest(revisionBytes)!==expectedRevision||await digest(parentBytes)!==revision.binding.parentReportSHA256)throw Error('mismatch');verified=true;$('integrity').textContent='Parent and evidence revision byte integrity verified locally. Research interpretation and authorship are not verified.';$('export').disabled=!candidates.length}catch{$('integrity').textContent='Browser integrity check unavailable or failed. Review export is disabled; use native archive verification.'}})();
        $('export').addEventListener('click',()=>{const reviewer=$('reviewer').value.trim(),decisions=candidates.filter(c=>drafts.has(c.id)).map(c=>drafts.get(c.id));if(!verified||!/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/.test(reviewer)){$('status').textContent='Enter a valid reviewer identifier after integrity verification.';return}if(!decisions.length||decisions.some(d=>!d.rationale.trim()||new TextEncoder().encode(d.rationale).length>4096)){$('status').textContent='Record at least one disposition and a rationale of at most 4,096 UTF-8 bytes for every decision.';return}const review={schema:'numivivo.org/neoantigen-evidence-review/v1',revisionSHA256:expectedRevision,reviewerID:reviewer,reviewedAt:new Date().toISOString().replace(/\.\d{3}Z$/,'Z'),decisions},url=URL.createObjectURL(new Blob([JSON.stringify(review,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='neoantigen-evidence-review.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Research review exported against this evidence revision. No clinical action was authorized.'});
        </script></body></html>
        """#
        return Data(html.utf8)
    }
}
